/**
 * Represents the arguments for the `dataAdd` and `dataRemove` events.
 * @hidden
 */
export interface DataEvent {
    /**
     * Specifies the index of the data item.
     */
    index: number;
    /**
     * Specifies the data item to add or remove.
     */
    dataItem: object;
}
